// Created: 2026-08-08

/**
 * stale-team-cleanup must not delete a LIVE session's team.
 *
 * This hook runs at SessionStart while other sessions are mid-flight, and
 * cleanupTeam() removes CC's own ~/.claude/teams/<name> AND
 * ~/.claude/tasks/<name>. A false positive destroys a live session's task list.
 *
 * Every case below FAILS against the pre-2026-08-08 implementation:
 *   - `if (!existsSync(configPath)) return true`  deleted a config-less
 *     directory at ANY age, including one created milliseconds ago.
 *   - the age came from the team dir's OWN mtime, which does not move when a
 *     nested task file is written, so a busy team read as idle.
 *   - `catch { return true }` turned an unreadable directory into a delete.
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync, utimesSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { isStaleTeam } from '../lib/agent-teams.js';

const HOURS = 3600_000;
let home: string;
let prevHome: string | undefined;

function team(name: string): string {
  const p = join(home, '.claude', 'teams', name);
  mkdirSync(p, { recursive: true });
  return p;
}

/** Backdate a path so it reads as `hoursAgo` old. */
function backdate(p: string, hoursAgo: number): void {
  const t = (Date.now() - hoursAgo * HOURS) / 1000;
  utimesSync(p, t, t);
}

beforeEach(() => {
  prevHome = process.env.HOME;
  home = mkdtempSync(join(tmpdir(), 'ork-teams-'));
  process.env.HOME = home;
  mkdirSync(join(home, '.claude', 'teams'), { recursive: true });
});

afterEach(() => {
  if (prevHome === undefined) delete process.env.HOME;
  else process.env.HOME = prevHome;
  rmSync(home, { recursive: true, force: true });
});

describe('isStaleTeam fails closed', () => {
  it('does NOT delete a just-created team that has no config.json yet', () => {
    // The exact race: a live session mkdir'd its team dir and has not written
    // config.json. Old code returned true here and deleted it out from under it.
    team('being-created');
    expect(isStaleTeam('being-created', 4)).toBe(false);
  });

  it('does NOT delete a config-less directory that is merely young', () => {
    const p = team('young-no-config');
    backdate(p, 1);
    expect(isStaleTeam('young-no-config', 4)).toBe(false);
  });

  it('does NOT delete a team whose nested task file is recent', () => {
    // Directory mtime only moves when DIRECT children change. Old code read
    // the top-level mtime and called an actively-writing team idle.
    const p = team('busy-nested');
    const nested = join(p, 'tasks', 'task-1');
    mkdirSync(nested, { recursive: true });
    writeFileSync(join(nested, 'state.json'), '{}');
    writeFileSync(join(p, 'config.json'), '{}');
    backdate(p, 9); // stale-looking container, live contents
    expect(isStaleTeam('busy-nested', 4)).toBe(false);
  });

  it('does not report a nonexistent team as stale', () => {
    expect(isStaleTeam('never-existed', 4)).toBe(false);
  });

  it('DOES delete a genuinely abandoned team', () => {
    // The gate must still do its job, or the fix is just a disable.
    const p = team('abandoned');
    writeFileSync(join(p, 'config.json'), '{}');
    backdate(join(p, 'config.json'), 9);
    backdate(p, 9);
    expect(isStaleTeam('abandoned', 4)).toBe(true);
  });

  it('DOES delete an old config-less orphan', () => {
    const p = team('old-orphan');
    backdate(p, 9);
    expect(isStaleTeam('old-orphan', 4)).toBe(true);
  });
});
